/** Recorridos completos tal como los usa la operación. */
export const ROUTES: string[] = RAW_ROUTES.split("\n").filter(Boolean);

export const splitStops = (route: string): string[] =>
  route
    .replace(/\//g, "-")
    .split("-")
    .map((s) => s.trim())
    .filter(Boolean);

export const normalizeStop = (s: string): string =>
  s
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

/** Paradas únicas del catálogo, con su nombre canónico. */
export const STOPS: { key: string; name: string }[] = (() => {
  const map = new Map<string, string>();
  for (const route of ROUTES) {
    for (const stop of splitStops(route)) {
      const key = normalizeStop(stop);
      if (key.length > 1 && !map.has(key)) map.set(key, stop);
    }
  }
  return [...map.entries()]
    .map(([key, name]) => ({ key, name }))
    .sort((a, b) => a.name.localeCompare(b.name));
})();

/** Tramos elementales (pares consecutivos) conocidos, sin dirección. */
export const LEGS: Set<string> = (() => {
  const set = new Set<string>();
  for (const route of ROUTES) {
    const stops = splitStops(route).map(normalizeStop);
    for (let i = 0; i < stops.length - 1; i++) {
      const a = stops[i]!;
      const b = stops[i + 1]!;
      if (a === b) continue;
      set.add(`${a}>${b}`);
      set.add(`${b}>${a}`);
    }
  }
  return set;
})();

const ROUTE_KEYS: Set<string> = new Set(
  ROUTES.map((r) => splitStops(r).map(normalizeStop).join(">")),
);

/**
 * Registra en tiempo de ejecución un recorrido nuevo (y sus tramos elementales),
 * para que pase a considerarse válido por el validador.
 */
export function registerRoute(stops: string[]): boolean {
  const clean = stops.map((s) => s.trim()).filter(Boolean);
  if (clean.length < 2) return false;
  const keys = clean.map(normalizeStop);
  clean.forEach((name, i) => {
    const key = keys[i]!;
    if (key.length > 1 && !STOPS.some((s) => s.key === key)) STOPS.push({ key, name });
  });
  for (let i = 0; i < keys.length - 1; i++) {
    const a = keys[i]!;
    const b = keys[i + 1]!;
    if (a === b) continue;
    LEGS.add(`${a}>${b}`);
    LEGS.add(`${b}>${a}`);
  }
  ROUTE_KEYS.add(keys.join(">"));
  return true;
}

export const isKnownRoute = (stops: string[]): boolean =>
  ROUTE_KEYS.has(stops.map(normalizeStop).join(">"));

export const isKnownLeg = (from: string, to: string): boolean =>
  LEGS.has(`${normalizeStop(from)}>${normalizeStop(to)}`);

/** Resuelve una parada escrita libremente al nombre canónico del catálogo. */
export function resolveStop(input: string): string | undefined {
  const key = normalizeStop(input);
  if (!key) return undefined;
  const exact = STOPS.find((s) => s.key === key);
  if (exact) return exact.name;
  const partial = STOPS.filter((s) => s.key.includes(key) || key.includes(s.key)).sort(
    (a, b) => a.key.length - b.key.length,
  );
  return key.length > 2 ? partial[0]?.name : undefined;
}

/** Continuaciones posibles desde una parada (para combinar tramos). */
export function nextStops(from: string): string[] {
  const key = normalizeStop(from);
  const out = new Set<string>();
  for (const leg of LEGS) {
    const [a, b] = leg.split(">");
    if (a === key && b) out.add(b);
  }
  return [...out]
    .map((k) => STOPS.find((s) => s.key === k)?.name ?? k)
    .sort((a, b) => a.localeCompare(b));
}
